                var ret = new ErrorMask();
                ret.EDID = this.EDID.Combine(rhs.EDID);
                ret.FULL = this.FULL.Combine(rhs.FULL);
                ret.Relations = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, FactionXNAMData.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.Relations?.Overall, rhs.Relations?.Overall), Noggog.ExceptionExt.Combine(this.Relations?.Specific, rhs.Relations?.Specific));
