                ret.VENV = this.VENV.Combine(rhs.VENV);
                ret.CRVA = this.CRVA.Combine(rhs.CRVA);
                ret.RankNumbers = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.RankNumbers?.Overall, rhs.RankNumbers?.Overall), Noggog.ExceptionExt.Combine(this.RankNumbers?.Specific, rhs.RankNumbers?.Specific));
                ret.RankMaleTitles = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.RankMaleTitles?.Overall, rhs.RankMaleTitles?.Overall), Noggog.ExceptionExt.Combine(this.RankMaleTitles?.Specific, rhs.RankMaleTitles?.Specific));
