                ret.PLVD = this.PLVD.Combine(rhs.PLVD, (l, r) => l.Combine(r));
                ret.Conditions = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, Condition.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.Conditions?.Overall, rhs.Conditions?.Overall), Noggog.ExceptionExt.Combine(this.Conditions?.Specific, rhs.Conditions?.Specific));
                ret.EntryChecks = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.EntryChecks?.Overall, rhs.EntryChecks?.Overall), Noggog.ExceptionExt.Combine(this.EntryChecks?.Specific, rhs.EntryChecks?.Specific));
                ret.FCRF = this.FCRF.Combine(rhs.FCRF);
                ret.FCOR = this.FCOR.Combine(rhs.FCOR);
                ret.FCBM = this.FCBM.Combine(rhs.FCBM);
