        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IFactionGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            foreach (var item in obj.Relations.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.DATA, out var DATAInfo))
            {
                yield return DATAInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ExteriorJailMarker, out var ExteriorJailMarkerInfo))
            {
                yield return ExteriorJailMarkerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.FollowerWaitMarker, out var FollowerWaitMarkerInfo))
            {
                yield return FollowerWaitMarkerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.StolenGoodsContainer, out var StolenGoodsContainerInfo))
            {
                yield return StolenGoodsContainerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.PlayerInventoryContainer, out var PlayerInventoryContainerInfo))
            {
                yield return PlayerInventoryContainerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SharedCrimeFactionList, out var SharedCrimeFactionListInfo))
            {
                yield return SharedCrimeFactionListInfo;
            }
            if (FormLinkInformation.TryFactory(obj.JailOutfit, out var JailOutfitInfo))
            {
                yield return JailOutfitInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (FormLinkInformation.TryFactory(obj.VendorBuySellList, out var VendorBuySellListInfo))
            {
                yield return VendorBuySellListInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MerchantContainer, out var MerchantContainerInfo))
            {
                yield return MerchantContainerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.VendorRespawnCell, out var VendorRespawnCellInfo))
            {
                yield return VendorRespawnCellInfo;
            }
            if (FormLinkInformation.TryFactory(obj.VendorCapResetGlobal, out var VendorCapResetGlobalInfo))
            {
                yield return VendorCapResetGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.VendorBuyCurrency, out var VendorBuyCurrencyInfo))
            {
                yield return VendorBuyCurrencyInfo;
            }
            foreach (var item in obj.RankNumbers)
            {
                yield return FormLinkInformation.Factory(item);
            }
            foreach (var item in obj.RankMaleTitles)
            {
                yield return FormLinkInformation.Factory(item);
            }
            foreach (var item in obj.RankFemaleTitles)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.FCRF, out var FCRFInfo))
            {
                yield return FCRFInfo;
            }
            if (FormLinkInformation.TryFactory(obj.FCOR, out var FCORInfo))
            {
                yield return FCORInfo;
            }
            if (FormLinkInformation.TryFactory(obj.FCBM, out var FCBMInfo))
            {
                yield return FCBMInfo;
            }
            if (obj.EntryCheckConditions is {} EntryCheckConditionsItem)
            {
                foreach (var item in EntryCheckConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.FCAF, out var FCAFInfo))
            {
                yield return FCAFInfo;
            }
            if (obj.FactionConditions is {} FactionConditionsItem)
            {
                foreach (var item in FactionConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            yield break;
        }
        
